export function inventoryStatus(card,quantity,goldExchange=false,mode='Same Rarity'){if(!Number.isInteger(quantity)||quantity<0)throw Error('Invalid quantity');return {owned:quantity>0,missing:quantity===0,duplicates:Math.max(0,quantity-1),tradeable:quantity>=2&&mode!=='No Trading',label:quantity===0?'LF':quantity===1||mode==='No Trading'?'Owned':'FT'};}
export function albumShareText(data,inventory,profile,mode,trades,gold=false,publicLink='',{removeLowStars=false,freeLowStars=false,showFoil=false}={}){
 if(!['Same Rarity','Flexible Rarity','Any Rarity','No Trading'].includes(mode)||!Number.isInteger(trades)||trades<0||trades>3)throw Error('Choose a valid trade mode and 0–3 trades left.');
 const uid=String(profile.game_id||'Not set').replace(/[\r\n`]/g,' ').trim(),modeLabel=mode==='Any Rarity'?'All Rarity':mode==='Same Rarity'?'Equal Rarity':mode;
 const lines=['🃏 **Autum Tales Album | UID : '+uid+'**',...(publicLink?['🌐 '+publicLink]:[]),modeLabel+' | Exchange attempt : '+trades+'/3'];
 if(mode==='No Trading'){const collected=data.cards.filter(c=>(inventory.get(c.number)?.quantity||0)>0);lines.push('Collected: '+collected.length+'/'+data.cards.length);if(showFoil)lines.push('Foil owned: '+(data.cards.filter(c=>inventory.get(c.number)?.has_foil).map(c=>c.number).join(', ')||'None marked'));return lines.join('\n')}
 const rows=kind=>{const result=[];for(const isGold of kind==='free'?[false]:[false,true]){if(isGold&&!gold)continue;for(const stars of kind==='free'?[1,2,3]:isGold?[4,5]:[1,2,3,4,5]){
  if(kind!=='free'&&stars<=3&&(removeLowStars||(kind==='ft'&&freeLowStars)))continue;
  const numbers=data.cards.filter(card=>card.stars===stars&&Boolean(card.gold)===isGold).filter(card=>{const quantity=inventory.get(card.number)?.quantity||0;return kind==='lf'?quantity===0:quantity>=2}).map(card=>kind!=='lf'&&inventory.get(card.number)?.trade_foil?card.number+' (Foil)':card.number);
  if(numbers.length)result.push('⭐️**'+stars+(isGold?' Gold':'')+'** : '+numbers.join(', '));
 }}return result};
 lines.push('','🔎 **Looking For**',...rows('lf'),'','🎁 **For Trade**',...rows('ft'));if(freeLowStars)lines.push('','🆓 **1–3⭐️ Free Cards**',...rows('free'));if(showFoil){const owned=data.cards.filter(c=>inventory.get(c.number)?.has_foil).map(c=>c.number);const offered=data.cards.filter(c=>(!c.gold||gold)&&!(c.stars<=3&&(removeLowStars||freeLowStars))&&inventory.get(c.number)?.trade_foil&&(inventory.get(c.number)?.quantity||0)>1).map(c=>c.number);lines.push('','✨ **Foil Owned**',owned.length?owned.join(', '):'None marked','✨ **Foil For Trade**',offered.length?offered.join(', '):'None offered');}lines.push('','📩 **DM me or reply!**');return lines.join('\n');
}
